func (m *Vote) legacyValues(insert bool) runtime.Values {
	values := make(runtime.Values)

	if insert {

		if !insert || !runtime.IsZero(m.Id) {

			values["id"] = m.Id

		}

	}

	if !insert || !runtime.IsZero(m.CreatedAt) {

		values["createdAt"] = m.CreatedAt

	}

	if !insert || !runtime.IsZero(m.UpdatedAt) {
		if !runtime.IsZero(m.UpdatedAt) && insert {

			values["updatedAt"] = m.UpdatedAt

		}
	}

	if !insert || !runtime.IsZero(m.DeletedAt) {

		if m.DeletedAt != nil {
			values["deletedAt"] = *m.DeletedAt
		} else {
			values["deletedAt"] = nil
		}

	}

	values["name"] = m.Name

	values["email"] = m.Email

	if !insert || !runtime.IsZero(m.Verified) {

		values["verified"] = m.Verified

	}

	values["networksId"] = m.NetworksId

	values["softwareId"] = m.SoftwareId

	values["embeddedId"] = m.EmbeddedId

	values["battleBotId"] = m.BattleBotId

	return values
}

